describe("PixelBrushCanvas draw pass", () => {
  let canvas2d: Canvas2DMock;

  beforeEach(() => {
    canvas2d = installCanvas2DMock({ height: SURFACE, width: SURFACE });
  });

  afterEach(() => {
    uninstallCanvas2DMock();
  });

  const setup = (
    props: Partial<Parameters<typeof PixelBrushCanvas>[0]> = {}
  ) => {
    const result = render(
      <PixelBrushCanvas
        height={GRID}
        pixelSize={PIXEL_SIZE}
        width={GRID}
        {...props}
      />
    );
    const canvas = result.container.querySelector("canvas");
    if (!canvas) {
      throw new Error("expected a canvas");
    }
    // jsdom implements none of the pointer-capture API.
    canvas.setPointerCapture = vi.fn();
    canvas.releasePointerCapture = vi.fn();
    canvas.hasPointerCapture = vi.fn(() => true);
    const context = canvas2d.contextFor(canvas);
    if (!context) {
      throw new Error("expected a 2D context");
    }
    return { ...result, canvas, context };
  };

  it("clears every cell of the grid on mount", () => {
    const { context } = setup();
    expect(context.setTransform).toHaveBeenCalled();
    expect(context.clearRect).toHaveBeenCalledTimes(GRID * GRID);
    expect(context.fillRect).not.toHaveBeenCalled();
  });

  it("fills the cells of an initial artwork", () => {
    const { context } = setup({
      initial: [
        [0, 1],
        [-1, 2],
      ],
    });
    expect(context.fillRect).toHaveBeenCalledTimes(3);
  });

  it("strokes gridlines when the grid is on", () => {
    const { context } = setup({ grid: true });
    expect(context.strokeRect).toHaveBeenCalledTimes(GRID * GRID);
  });

  it("paints a cell with the pencil and reports the change", () => {
    const onChange = vi.fn();
    const { canvas, context } = setup({ onChange });

    context.resetRecords();
    fireEvent.pointerDown(canvas, at(2, 3));

    expect(context.fillRect).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledTimes(1);
    const pixels = onChange.mock.calls[0][0] as Uint8Array;
    expect(pixels[3 * GRID + 2]).toBe(1);
  });

  it("drags a pencil stroke across cells and ignores repeats", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ onChange });

    fireEvent.pointerDown(canvas, at(0, 0));
    fireEvent.pointerMove(canvas, at(1, 0));
    fireEvent.pointerMove(canvas, at(1, 0));
    fireEvent.pointerMove(canvas, at(2, 0));
    fireEvent.pointerUp(canvas, at(2, 0));

    expect(onChange).toHaveBeenCalledTimes(3);
    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(Array.from(pixels.subarray(0, 3))).toEqual([1, 1, 1]);
  });

  it("erases a painted cell", () => {
    const onChange = vi.fn();
    const { canvas } = setup({
      brush: "eraser",
      initial: [[0, 0, 0]],
      onChange,
    });

    fireEvent.pointerDown(canvas, at(1, 0));

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(pixels[1]).toBe(0);
    expect(pixels[0]).toBe(1);
  });

  it("floods the whole empty grid with the fill tool", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ brush: "fill", onChange });

    fireEvent.pointerDown(canvas, at(4, 4));

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(pixels.every((value) => value === 1)).toBe(true);
  });

  it("does nothing when filling a region that already holds the colour", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ brush: "fill", onChange });

    fireEvent.pointerDown(canvas, at(0, 0));
    onChange.mockClear();
    fireEvent.pointerDown(canvas, at(5, 5));

    expect(onChange).not.toHaveBeenCalled();
  });

  it("commits a Bresenham line between press and release", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ brush: "line", onChange });

    fireEvent.pointerDown(canvas, at(0, 0));
    fireEvent.pointerUp(canvas, at(3, 3));

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    for (let index = 0; index < 4; index++) {
      expect(pixels[index * GRID + index]).toBe(1);
    }
  });

  it("commits a rectangle outline between press and release", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ brush: "rect", onChange });

    fireEvent.pointerDown(canvas, at(1, 1));
    fireEvent.pointerUp(canvas, at(4, 3));

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    // Corners lit, interior untouched.
    expect(pixels[1 * GRID + 1]).toBe(1);
    expect(pixels[3 * GRID + 4]).toBe(1);
    expect(pixels[2 * GRID + 2]).toBe(0);
  });

  it("paints and navigates from the keyboard", () => {
    const onChange = vi.fn();
    setup({ onChange });
    const surface = screen.getByRole("application");

    fireEvent.keyDown(surface, { key: "ArrowRight" });
    fireEvent.keyDown(surface, { key: "ArrowDown" });
    fireEvent.keyDown(surface, { key: " " });

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(pixels[1 * GRID + 1]).toBe(1);
    expect(screen.getByText(/Column 2, row 2/)).toBeInTheDocument();

    fireEvent.keyDown(surface, { key: "ArrowLeft" });
    fireEvent.keyDown(surface, { key: "ArrowUp" });
    expect(screen.getByText(/Column 1, row 1/)).toBeInTheDocument();
  });

  it("switches tools from their keyboard shortcuts", () => {
    const onBrushChange = vi.fn();
    setup({ onBrushChange });
    const surface = screen.getByRole("application");

    fireEvent.keyDown(surface, { key: "e" });
    fireEvent.keyDown(surface, { key: "g" });
    fireEvent.keyDown(surface, { key: "b" });
    fireEvent.keyDown(surface, { key: "q" });

    expect(onBrushChange.mock.calls.map(([brush]) => brush)).toEqual([
      "eraser",
      "fill",
      "pencil",
    ]);
  });

  it("draws a keyboard line between two anchored presses", () => {
    const onChange = vi.fn();
    setup({ brush: "line", onChange });
    const surface = screen.getByRole("application");

    fireEvent.keyDown(surface, { key: " " });
    expect(
      screen.getByText(/Anchor set at column 1, row 1/)
    ).toBeInTheDocument();

    fireEvent.keyDown(surface, { key: "ArrowRight" });
    fireEvent.keyDown(surface, { key: "ArrowRight" });
    fireEvent.keyDown(surface, { key: " " });

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(Array.from(pixels.subarray(0, 3))).toEqual([1, 1, 1]);
  });

  it("reverts the last stroke with the undo shortcut", () => {
    const onChange = vi.fn();
    const { canvas } = setup({ onChange });
    const surface = screen.getByRole("application");

    fireEvent.pointerDown(canvas, at(2, 2));
    fireEvent.keyDown(surface, { ctrlKey: true, key: "z" });

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(pixels[2 * GRID + 2]).toBe(0);
  });

  it("ignores undo with an empty history", () => {
    const onChange = vi.fn();
    setup({ onChange });
    fireEvent.keyDown(screen.getByRole("application"), {
      key: "z",
      metaKey: true,
    });
    expect(onChange).not.toHaveBeenCalled();
  });

  it("exposes clear, undo, getPixels and toDataURL through the ref", () => {
    const ref = createRef<PixelBrushCanvasHandle>();
    const { canvas, context } = setup({ initial: [[0, 0]], ref });

    expect(Array.from(ref.current?.getPixels() ?? [])).toContain(1);
    expect(ref.current?.toDataURL()).toMatch(/^data:image\/png/);
    expect(canvas.toDataURL).toBeDefined();

    context.resetRecords();
    ref.current?.clear();
    expect(ref.current?.getPixels().every((value) => value === 0)).toBe(true);
    expect(context.clearRect).toHaveBeenCalledTimes(GRID * GRID);

    ref.current?.undo();
    expect(Array.from(ref.current?.getPixels() ?? [])).toContain(1);
  });

  it("follows controlled brush and colour props", () => {
    const onChange = vi.fn();
    const { canvas, rerender } = setup({ color: 0, onChange });

    rerender(
      <PixelBrushCanvas
        brush="pencil"
        color={4}
        height={GRID}
        onChange={onChange}
        pixelSize={PIXEL_SIZE}
        width={GRID}
      />
    );
    fireEvent.pointerDown(canvas, at(0, 0));

    const pixels = onChange.mock.calls.at(-1)?.[0] as Uint8Array;
    expect(pixels[0]).toBe(5);
  });

  it("selects colours and tools from the tool palette", () => {
    const onBrushChange = vi.fn();
    const onColorChange = vi.fn();
    setup({ onBrushChange, onColorChange, palette: ["#000000", "#ffffff"] });

    fireEvent.click(screen.getByRole("button", { name: /Select color 2/ }));
    fireEvent.click(screen.getByRole("button", { name: /Rectangle tool/ }));

    expect(onColorChange).toHaveBeenCalledWith(1);
    expect(onBrushChange).toHaveBeenCalledWith("rect");
  });

  it("reallocates the buffer when the grid size changes", () => {
    const { rerender } = setup();
    rerender(
      <PixelBrushCanvas height={GRID * 2} pixelSize={PIXEL_SIZE} width={GRID} />
    );
    expect(canvas2d.paintCount()).toBeGreaterThan(GRID * GRID);
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import { motion, useReducedMotion } from "motion/react";
import {
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type Ref,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

export type PixelBrushCanvasBrush =
  | "pencil"
  | "eraser"
  | "fill"
  | "line"
  | "rect";

export interface PixelBrushCanvasHandle {
  /** Erases every pixel back to the empty state. */
  clear: () => void;
  /** Returns a copy of the raw pixel buffer (palette indices, 0 = empty). */
  getPixels: () => Uint8Array;
  /** Exports the current drawing as a PNG data URL. */
  toDataURL: () => string;
  /** Reverts the last committed stroke, fill, line, rect or clear. */
  undo: () => void;
}

export interface PixelBrushCanvasProps {
  /** Currently active brush tool. Uncontrolled if omitted. */
  brush?: PixelBrushCanvasBrush;
  className?: string;
  /** Index into `palette` for the active paint color. Uncontrolled if omitted. */
  color?: number;
  /** Show gridlines between pixel cells. */
  grid?: boolean;
  /** Height of the art grid, in pixel cells (not CSS px). */
  height?: number;
  /** Optional initial artwork as a 2D array (rows of `height`, cols of `width`) of palette indices. Negative values mean empty. */
  initial?: number[][];
  onBrushChange?: (brush: PixelBrushCanvasBrush) => void;
  /** Fires with a snapshot of the pixel buffer on every mutation. */
  onChange?: (pixels: Uint8Array) => void;
  onColorChange?: (color: number) => void;
  /** Available paint colors, as CSS color strings. */
  palette?: string[];
  /** Size of a single pixel cell, in CSS px. */
  pixelSize?: number;
  ref?: Ref<PixelBrushCanvasHandle>;
  /** Render the built-in color/brush palette below the canvas. */
  showTools?: boolean;
  /** Width of the art grid, in pixel cells (not CSS px). */
  width?: number;
}

interface Cell {
  x: number;
  y: number;
}

interface BoundingBox {
  maxX: number;
  maxY: number;
  minX: number;
  minY: number;
}

interface BrushOption {
  label: string;
  shortcut?: string;
  value: PixelBrushCanvasBrush;
}

const DEFAULT_GRID_WIDTH = 16;
const DEFAULT_GRID_HEIGHT = 16;
const DEFAULT_PIXEL_SIZE = 20;
const MAX_DEVICE_PIXEL_RATIO = 2;
const MAX_UNDO_STEPS = 50;
const GRID_LINE_WIDTH = 1;
const EMPTY_CELL_VALUE = 0;
const GRID_LINE_COLOR = "rgba(120, 120, 120, 0.35)";

const DEFAULT_PALETTE: string[] = [
  "#1f2937",
  "#ef4444",
  "#f97316",
  "#facc15",
  "#22c55e",
  "#0ea5e9",
  "#6366f1",
  "#ec4899",
  "#ffffff",
];

const BRUSH_OPTIONS: BrushOption[] = [
  { label: "Pencil", shortcut: "B", value: "pencil" },
  { label: "Eraser", shortcut: "E", value: "eraser" },
  { label: "Fill", shortcut: "G", value: "fill" },
  { label: "Line", value: "line" },
  { label: "Rectangle", value: "rect" },
];

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const createInitialPixels = (
  gridWidth: number,
  gridHeight: number,
  initial?: number[][]
): Uint8Array => {
  const pixels = new Uint8Array(gridWidth * gridHeight);
  if (!initial) {
    return pixels;
  }
  for (let y = 0; y < gridHeight; y++) {
    const row = initial[y];
    if (!row) {
      continue;
    }
    for (let x = 0; x < gridWidth; x++) {
      const value = row[x];
      if (value === undefined || value < 0) {
        continue;
      }
      pixels[y * gridWidth + x] = value + 1;
    }
  }
  return pixels;
};

const drawCell = (
  ctx: CanvasRenderingContext2D,
  pixels: Uint8Array,
  gridWidth: number,
  x: number,
  y: number,
  cellSize: number,
  palette: string[],
  showGrid: boolean
) => {
  const value = pixels[y * gridWidth + x];
  const left = x * cellSize;
  const top = y * cellSize;
  ctx.clearRect(left, top, cellSize, cellSize);
  if (value !== EMPTY_CELL_VALUE) {
    ctx.fillStyle = palette[value - 1] ?? palette[0] ?? "#000000";
    ctx.fillRect(left, top, cellSize, cellSize);
  }
  if (showGrid) {
    ctx.strokeStyle = GRID_LINE_COLOR;
    ctx.lineWidth = GRID_LINE_WIDTH;
    ctx.strokeRect(left + 0.5, top + 0.5, cellSize - 1, cellSize - 1);
  }
};

const drawRegion = (
  ctx: CanvasRenderingContext2D,
  pixels: Uint8Array,
  gridWidth: number,
  gridHeight: number,
  cellSize: number,
  palette: string[],
  showGrid: boolean,
  box: BoundingBox
) => {
  const startX = Math.max(0, box.minX);
  const startY = Math.max(0, box.minY);
  const endX = Math.min(gridWidth - 1, box.maxX);
  const endY = Math.min(gridHeight - 1, box.maxY);
  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      drawCell(ctx, pixels, gridWidth, x, y, cellSize, palette, showGrid);
    }
  }
};

/** Iterative (stack-based) flood fill — never recursive, so it cannot blow the call stack. */
const floodFillIterative = (
  pixels: Uint8Array,
  gridWidth: number,
  gridHeight: number,
  startX: number,
  startY: number,
  newValue: number
): BoundingBox | null => {
  const targetValue = pixels[startY * gridWidth + startX];
  if (targetValue === newValue) {
    return null;
  }
  const stack: Cell[] = [{ x: startX, y: startY }];
  const box: BoundingBox = {
    maxX: startX,
    maxY: startY,
    minX: startX,
    minY: startY,
  };
  while (stack.length > 0) {
    const cell = stack.pop();
    if (!cell) {
      break;
    }
    const { x, y } = cell;
    if (x < 0 || x >= gridWidth || y < 0 || y >= gridHeight) {
      continue;
    }
    if (pixels[y * gridWidth + x] !== targetValue) {
      continue;
    }
    pixels[y * gridWidth + x] = newValue;
    box.minX = Math.min(box.minX, x);
    box.maxX = Math.max(box.maxX, x);
    box.minY = Math.min(box.minY, y);
    box.maxY = Math.max(box.maxY, y);
    stack.push(
      { x: x + 1, y },
      { x: x - 1, y },
      { x, y: y + 1 },
      { x, y: y - 1 }
    );
  }
  return box;
};

/** Bresenham line rasterization, bounded by the known max step count. */
const getLineCells = (start: Cell, end: Cell): Cell[] => {
  const cells: Cell[] = [];
  const dx = Math.abs(end.x - start.x);
  const dy = Math.abs(end.y - start.y);
  const stepX = end.x >= start.x ? 1 : -1;
  const stepY = end.y >= start.y ? 1 : -1;
  const maxSteps = Math.max(dx, dy) + 1;
  let { x, y } = start;
  let error = dx - dy;
  for (let step = 0; step < maxSteps; step++) {
    cells.push({ x, y });
    if (x === end.x && y === end.y) {
      break;
    }
    const doubledError = error * 2;
    if (doubledError > -dy) {
      error -= dy;
      x += stepX;
    }
    if (doubledError < dx) {
      error += dx;
      y += stepY;
    }
  }
  return cells;
};

const getRectOutlineCells = (start: Cell, end: Cell): Cell[] => {
  const minX = Math.min(start.x, end.x);
  const maxX = Math.max(start.x, end.x);
  const minY = Math.min(start.y, end.y);
  const maxY = Math.max(start.y, end.y);
  const cells: Cell[] = [];
  for (let x = minX; x <= maxX; x++) {
    cells.push({ x, y: minY });
    if (maxY !== minY) {
      cells.push({ x, y: maxY });
    }
  }
  for (let y = minY; y <= maxY; y++) {
    cells.push({ x: minX, y });
    if (maxX !== minX) {
      cells.push({ x: maxX, y });
    }
  }
  return cells;
};

const getCellFromPoint = (
  clientX: number,
  clientY: number,
  rect: DOMRect,
  gridWidth: number,
  gridHeight: number,
  cellSize: number
): Cell => {
  const scaleX = rect.width / (gridWidth * cellSize) || 1;
  const scaleY = rect.height / (gridHeight * cellSize) || 1;
  const rawX = (clientX - rect.left) / scaleX;
  const rawY = (clientY - rect.top) / scaleY;
  return {
    x: clamp(Math.floor(rawX / cellSize), 0, gridWidth - 1),
    y: clamp(Math.floor(rawY / cellSize), 0, gridHeight - 1),
  };
};

const describeValue = (value: number, palette: string[]): string =>
  value === EMPTY_CELL_VALUE
    ? "empty"
    : (palette[value - 1] ?? "unknown color");

interface ToolPaletteProps {
  brush: PixelBrushCanvasBrush;
  colorIndex: number;
  onSelectBrush: (brush: PixelBrushCanvasBrush) => void;
  onSelectColor: (index: number) => void;
  palette: string[];
}

const ToolPalette = ({
  brush,
  colorIndex,
  onSelectBrush,
  onSelectColor,
  palette,
}: ToolPaletteProps) => {
  const shouldReduceMotion = useReducedMotion();
  const brushIndicatorId = `pixel-brush-tool-${useId()}`;

  return (
    <div className="flex flex-wrap items-center gap-3">
      <fieldset
        aria-label="Color palette"
        className="m-0 flex items-center gap-1.5 border-0 p-0"
      >
        {palette.map((hex, index) => {
          const isSelected = index === colorIndex;
          return (
            <button
              aria-label={`Select color ${index + 1}: ${hex}`}
              aria-pressed={isSelected}
              className={cn(
                "relative flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-full",
                "shadow-[inset_0_0_0_1px_rgb(0_0_0/0.12)] outline-none dark:shadow-[inset_0_0_0_1px_rgb(255_255_255/0.16)]",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              )}
              // biome-ignore lint/suspicious/noArrayIndexKey: palette is a flat color list with no stable id and colors may repeat
              key={`${hex}-${index}`}
              onClick={() => onSelectColor(index)}
              style={{ backgroundColor: hex }}
              type="button"
            >
              {isSelected && (
                // A brand ring around a swatch fights the colour the swatch is
                // showing. The selection halo is neutral chrome instead — the
                // gap-then-ring every colour picker uses — so it reads the same
                // against every hue in the palette.
                <motion.span
                  animate={{ opacity: 1, scale: 1 }}
                  aria-hidden="true"
                  className="absolute inset-0 rounded-full ring-2 ring-foreground ring-offset-2 ring-offset-background"
                  initial={
                    shouldReduceMotion
                      ? { opacity: 1, scale: 1 }
                      : { opacity: 0, scale: 0.6 }
                  }
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { bounce: 0.1, duration: 0.25, type: "spring" }
                  }
                />
              )}
            </button>
          );
        })}
      </fieldset>
      {/* Tool selection borrows the language of `Tabs`: the whole
          group is a recessed track and the active tool is a solid chip raised
          out of it, which reads instantly at this size without any fill. */}
      <fieldset
        aria-label="Brush tools"
        className="m-0 flex items-center gap-0.5 rounded-lg border-0 bg-foreground/[0.05] p-1 dark:bg-foreground/[0.09]"
      >
        {BRUSH_OPTIONS.map((option) => {
          const isActive = option.value === brush;
          return (
            <button
              aria-label={
                option.shortcut
                  ? `${option.label} tool (shortcut ${option.shortcut})`
                  : `${option.label} tool`
              }
              aria-pressed={isActive}
              className={cn(
                "relative cursor-pointer rounded-md px-2.5 py-1.5 font-medium text-xs outline-none",
                "transition-colors duration-150 ease-out",
                "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background",
                isActive
                  ? "text-foreground"
                  : "text-muted-foreground hover:text-foreground"
              )}
              key={option.value}
              onClick={() => onSelectBrush(option.value)}
              type="button"
            >
              {isActive && (
                <motion.span
                  aria-hidden="true"
                  className="absolute inset-0 rounded-md bg-background shadow-[0_0_0_1px_rgb(0_0_0/0.07),0_1px_2px_rgb(0_0_0/0.08)] dark:bg-foreground/[0.14] dark:shadow-[0_0_0_1px_rgb(255_255_255/0.10)]"
                  layoutId={brushIndicatorId}
                  transition={
                    shouldReduceMotion
                      ? { duration: 0 }
                      : { bounce: 0.1, duration: 0.25, type: "spring" }
                  }
                />
              )}
              <span className="relative">{option.label}</span>
            </button>
          );
        })}
      </fieldset>
    </div>
  );
};

const PixelBrushCanvas = ({
  brush,
  className,
  color,
  grid = false,
  height = DEFAULT_GRID_HEIGHT,
  initial,
  onBrushChange,
  onChange,
  onColorChange,
  palette = DEFAULT_PALETTE,
  pixelSize = DEFAULT_PIXEL_SIZE,
  ref,
  showTools = true,
  width = DEFAULT_GRID_WIDTH,
}: PixelBrushCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const pixelsRef = useRef<Uint8Array>(
    createInitialPixels(width, height, initial)
  );
  const undoStackRef = useRef<Uint8Array[]>([]);
  const isPaintingRef = useRef(false);
  const lastPaintedRef = useRef<Cell | null>(null);
  const dragStartRef = useRef<Cell | null>(null);
  const anchorRef = useRef<Cell | null>(null);

  const [internalColor, setInternalColor] = useState(color ?? 0);
  const [internalBrush, setInternalBrush] = useState<PixelBrushCanvasBrush>(
    brush ?? "pencil"
  );
  const [cursor, setCursor] = useState<Cell>({ x: 0, y: 0 });
  const [announcement, setAnnouncement] = useState("");

  useEffect(() => {
    if (color !== undefined) {
      setInternalColor(color);
    }
  }, [color]);

  useEffect(() => {
    if (brush !== undefined) {
      setInternalBrush(brush);
    }
  }, [brush]);

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    if (pixelsRef.current.length !== width * height) {
      pixelsRef.current = createInitialPixels(width, height, initial);
      undoStackRef.current = [];
    }
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DEVICE_PIXEL_RATIO);
    const cssWidth = width * pixelSize;
    const cssHeight = height * pixelSize;
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;
    canvas.width = Math.round(cssWidth * dpr);
    canvas.height = Math.round(cssHeight * dpr);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawRegion(
      ctx,
      pixelsRef.current,
      width,
      height,
      pixelSize,
      palette,
      grid,
      {
        maxX: width - 1,
        maxY: height - 1,
        minX: 0,
        minY: 0,
      }
    );
  }, [width, height, pixelSize, palette, grid, initial]);

  const redrawRegion = useCallback(
    (box: BoundingBox) => {
      const ctx = canvasRef.current?.getContext("2d");
      if (!ctx) {
        return;
      }
      drawRegion(
        ctx,
        pixelsRef.current,
        width,
        height,
        pixelSize,
        palette,
        grid,
        box
      );
    },
    [width, height, pixelSize, palette, grid]
  );

  const notifyChange = useCallback(() => {
    onChange?.(pixelsRef.current.slice());
  }, [onChange]);

  const pushUndoSnapshot = useCallback(() => {
    const stack = undoStackRef.current;
    if (stack.length >= MAX_UNDO_STEPS) {
      stack.shift();
    }
    stack.push(pixelsRef.current.slice());
  }, []);

  const announceFocusedCell = (x: number, y: number) => {
    const value = pixelsRef.current[y * width + x];
    setAnnouncement(
      `Column ${x + 1}, row ${y + 1}. Color: ${describeValue(value, palette)}.`
    );
  };

  const setCellValue = (x: number, y: number, value: number): boolean => {
    if (pixelsRef.current[y * width + x] === value) {
      return false;
    }
    pixelsRef.current[y * width + x] = value;
    redrawRegion({ maxX: x, maxY: y, minX: x, minY: y });
    return true;
  };

  const commitCells = (cells: Cell[], value: number) => {
    pushUndoSnapshot();
    let changed = false;
    const box: BoundingBox = { maxX: -1, maxY: -1, minX: width, minY: height };
    for (const cell of cells) {
      if (cell.x < 0 || cell.x >= width || cell.y < 0 || cell.y >= height) {
        continue;
      }
      if (pixelsRef.current[cell.y * width + cell.x] === value) {
        continue;
      }
      pixelsRef.current[cell.y * width + cell.x] = value;
      changed = true;
      box.minX = Math.min(box.minX, cell.x);
      box.minY = Math.min(box.minY, cell.y);
      box.maxX = Math.max(box.maxX, cell.x);
      box.maxY = Math.max(box.maxY, cell.y);
    }
    if (changed) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const applyFillAt = (x: number, y: number) => {
    pushUndoSnapshot();
    const box = floodFillIterative(
      pixelsRef.current,
      width,
      height,
      x,
      y,
      internalColor + 1
    );
    if (box) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const clear = useCallback(() => {
    pushUndoSnapshot();
    pixelsRef.current.fill(EMPTY_CELL_VALUE);
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, pushUndoSnapshot, redrawRegion, notifyChange]);

  const undo = useCallback(() => {
    const snapshot = undoStackRef.current.pop();
    if (!snapshot) {
      return;
    }
    pixelsRef.current = snapshot;
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, redrawRegion, notifyChange]);

  useImperativeHandle(
    ref,
    () => ({
      clear,
      getPixels: () => pixelsRef.current.slice(),
      toDataURL: () => canvasRef.current?.toDataURL() ?? "",
      undo,
    }),
    [clear, undo]
  );

  const selectBrush = (next: PixelBrushCanvasBrush) => {
    setInternalBrush(next);
    anchorRef.current = null;
    onBrushChange?.(next);
  };

  const selectColor = (index: number) => {
    setInternalColor(index);
    onColorChange?.(index);
  };

  const handlePointerDown = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    wrapperRef.current?.focus();
    setCursor(cell);

    if (internalBrush === "pencil" || internalBrush === "eraser") {
      event.currentTarget.setPointerCapture(event.pointerId);
      isPaintingRef.current = true;
      lastPaintedRef.current = null;
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cell.x, cell.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      lastPaintedRef.current = cell;
    } else if (internalBrush === "fill") {
      applyFillAt(cell.x, cell.y);
    } else {
      dragStartRef.current = cell;
    }
    announceFocusedCell(cell.x, cell.y);
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (!isPaintingRef.current) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    const last = lastPaintedRef.current;
    if (last && last.x === cell.x && last.y === cell.y) {
      return;
    }
    const value =
      internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
    if (setCellValue(cell.x, cell.y, value)) {
      notifyChange();
    }
    lastPaintedRef.current = cell;
    setCursor(cell);
  };

  const handlePointerUp = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (isPaintingRef.current) {
      isPaintingRef.current = false;
      lastPaintedRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
      return;
    }
    const start = dragStartRef.current;
    if (start && (internalBrush === "line" || internalBrush === "rect")) {
      const rect = event.currentTarget.getBoundingClientRect();
      const end = getCellFromPoint(
        event.clientX,
        event.clientY,
        rect,
        width,
        height,
        pixelSize
      );
      const cells =
        internalBrush === "line"
          ? getLineCells(start, end)
          : getRectOutlineCells(start, end);
      commitCells(cells, internalColor + 1);
      announceFocusedCell(end.x, end.y);
    }
    dragStartRef.current = null;
  };

  const moveCursor = (dx: number, dy: number) => {
    const nextX = clamp(cursor.x + dx, 0, width - 1);
    const nextY = clamp(cursor.y + dy, 0, height - 1);
    setCursor({ x: nextX, y: nextY });
    announceFocusedCell(nextX, nextY);
  };

  const paintAtCursor = () => {
    if (internalBrush === "pencil" || internalBrush === "eraser") {
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cursor.x, cursor.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      announceFocusedCell(cursor.x, cursor.y);
    } else if (internalBrush === "fill") {
      applyFillAt(cursor.x, cursor.y);
      announceFocusedCell(cursor.x, cursor.y);
    } else {
      const anchor = anchorRef.current;
      if (!anchor) {
        anchorRef.current = { x: cursor.x, y: cursor.y };
        setAnnouncement(
          `Anchor set at column ${cursor.x + 1}, row ${cursor.y + 1}. Move and press space again to finish.`
        );
        return;
      }
      const cells =
        internalBrush === "line"
          ? getLineCells(anchor, cursor)
          : getRectOutlineCells(anchor, cursor);
      commitCells(cells, internalColor + 1);
      anchorRef.current = null;
      announceFocusedCell(cursor.x, cursor.y);
    }
  };

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const isUndoShortcut =
      (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "z";
    if (isUndoShortcut) {
      event.preventDefault();
      undo();
      return;
    }
    switch (event.key) {
      case "ArrowUp": {
        event.preventDefault();
        moveCursor(0, -1);
        return;
      }
      case "ArrowDown": {
        event.preventDefault();
        moveCursor(0, 1);
        return;
      }
      case "ArrowLeft": {
        event.preventDefault();
        moveCursor(-1, 0);
        return;
      }
      case "ArrowRight": {
        event.preventDefault();
        moveCursor(1, 0);
        return;
      }
      case " ":
      case "Spacebar": {
        event.preventDefault();
        paintAtCursor();
        return;
      }
      default:
        break;
    }
    const lowerKey = event.key.toLowerCase();
    if (lowerKey === "e") {
      selectBrush("eraser");
    } else if (lowerKey === "b") {
      selectBrush("pencil");
    } else if (lowerKey === "g") {
      selectBrush("fill");
    }
  };

  return (
    <div className={cn("inline-flex flex-col gap-3", className)}>
      <div className="inline-block rounded-lg border border-border bg-muted/40 p-2">
        {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: role="application" is the keyboard-operable pixel grid; no semantic element models 2D arrow-key navigation */}
        <div
          aria-label="Pixel art drawing canvas"
          className="relative inline-block rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-brand"
          onKeyDown={handleKeyDown}
          ref={wrapperRef}
          role="application"
          // biome-ignore lint/a11y/noNoninteractiveTabindex: role="application" must be focusable to be keyboard-operable
          tabIndex={0}
        >
          <canvas
            className="block touch-none rounded-sm"
            onPointerDown={handlePointerDown}
            onPointerLeave={handlePointerUp}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            ref={canvasRef}
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute border-2 border-brand"
            style={{
              height: pixelSize,
              left: cursor.x * pixelSize,
              top: cursor.y * pixelSize,
              width: pixelSize,
            }}
          />
          <span aria-live="polite" className="sr-only">
            {announcement}
          </span>
        </div>
      </div>
      {showTools ? (
        <ToolPalette
          brush={internalBrush}
          colorIndex={internalColor}
          onSelectBrush={selectBrush}
          onSelectColor={selectColor}
          palette={palette}
        />
      ) : null}
    </div>
  );
};

export default PixelBrushCanvas;

