  const ctx = useContext(DelayContext);

  return (
    <PreviewCardPrimitive.Trigger
      closeDelay={closeDelay ?? ctx.closeDelay}
      data-slot="preview-card-trigger"
      delay={delay ?? ctx.delay}
      {...props}
    />
  );
