export const PreviewCardArrow = ({
  className,
  ...props
}: PreviewCardArrowProps) => (
  <PreviewCardPrimitive.Arrow
    className={cn(ARROW_CLASS, className)}
    data-slot="preview-card-arrow"
    {...props}
  />
